-- ════════════════════════════════════════════════════════
-- 255 — Huitième recensement : l'atelier de Puriscal remis d'aplomb
--       (Vegas de Santiago, Casdagli, Selected Tobacco et ses trois
--       marques, Bombay Tobak, Brun del Ré, fiche du Costa Rica)
-- ────────────────────────────────────────────────────────
-- CE QU'ON A TROUVÉ. Le réexamen de Puriscal (7 octobre) a établi que
-- Tabacos de Costa Rica S.A. est l'atelier de Vegas de Santiago sous son
-- nom actuel (Casdagli : « alors connue sous le nom de Vegas Santiago »),
-- et que cet atelier n'appartient pas à Marc Niehaus : La Nación nomme
-- Olman León « propriétaire de la fábrica » en 2011, Cigar Coop nomme
-- Andrés León propriétaire et exploitant en 2019. La fiche Vegas de
-- Santiago disait l'inverse (« Marc Niehaus l'a fondée »). Relue sur les
-- pages de la maison (cigars-vegasantiago.biz), de ses distributeurs et de
-- la presse, elle se corrige sur quatre points :
--
-- ── CE QUI CHANGE ───────────────────────────────────────
--   Fondateur   Deux versions écrites, attribuées, sans trancher : Marc
--               Niehaus seul (Casagranda, distributeur allemand) ; les
--               familles Niehaus et Guzmán ensemble (Cigarrspecialisten,
--               détaillant suédois). La maison ne nomme aucun fondateur et
--               présente Marc Niehaus comme partenaire et responsable des
--               ventes internationales. `founded` : « Non précisée —
--               Guzmán et Niehaus, Puriscal ».
--   Dates       1997 pour la manufacture familiale Tabacos de Costa Rica
--               (Casagranda) ; 1998 pour l'ouverture de la fabrique (un
--               entretien avec Marc Niehaus sur vdg-cigars.com) ; aucune
--               page ne date la marque.
--   Propriétés  L'atelier : Olman León (2011), Andrés León (2019), nommés
--               chacun avec sa page ; aucune page ne dit leur parenté,
--               la fiche ne parle donc pas de « famille León Guzmán ».
--   Feuilles    « Elle cultive ce qu'elle roule » tombe : la maison écrit
--               elle-même cultiver une part de ses feuilles et importer le
--               reste (Nicaragua, Équateur, États-Unis, Indonésie,
--               Caraïbes) ; La Nación écrit que la production de tabac a
--               cessé à Puriscal à la récolte 1997-1998. Les capes « Tabac
--               de Puriscal » des trois lignes étaient fausses : Chaman et
--               Don Luis sont en Connecticut d'Équateur, Reserva sans
--               origine donnée ; El Puro (Red Label), dite entièrement
--               costaricienne par la maison, entre en gamme.
--   Ailleurs    Casdagli (la culture à Puriscal passe à la maison Vegas de
--               Santiago, La Nación en regard) ; Bombay Tobak (« troisième
--               marque » périmée, atelier nommé comme Casdagli le nomme) ;
--               Atabey, Bandolero et Byron (fabrique nommée : Tabacos de
--               Costa Rica S.A., Cigar Coop 2019, 2023 et 2025) ;
--               Selected Tobacco (sources datées seulement) ; Brun del Ré
--               (dernier paragraphe : sa comparaison avec « la seule du
--               pays qui cultive » tombe avec elle).
--   Pays        Fiche du Costa Rica : les `desc` de Vegas de Santiago et
--               de Bombay Tobak, la phrase des `notes` sur Puriscal, « dix
--               fiches » devenu douze, « Selected Tobacco (Puriscal) » ôté
--               des tabacaleras (c'est une marque de l'atelier, pas une
--               fabrique). L'anglais des notes était relu : il est relu de
--               nouveau par expert-traduction (quatre retouches : « — plus »,
--               « has », « estate », « no press at all ») et garde son
--               statut `relu`, pour que le cliquet des relues (556) tienne.
--   Salon       Arturo Fuente — Boutique Santiago (lounges 182) : son chinois
--               et son arabe étaient du français semé de particules
--               (« La بوتيك famille Fuente… ») ; le volume arabe, à 0,4118 du
--               français, est passé sous la moitié de la médiane de sa
--               langue quand cette migration a déplacé la médiane. Refaits
--               sur le français actuel, sans un fait de plus (comme la 246).
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Fondateur de Vegas de Santiago, 1997 ou 1998 pour la fabrique ; chaman
-- ou El Mystico pour une même ligne ; liant de Chaman, Nicaragua ou Costa
-- Rica et Nicaragua selon deux pages de la maison ; culture à Puriscal,
-- plus de quatre-vingts ans selon la maison, arrêtée en 1997-1998 selon La
-- Nación.
--
-- ── CE QUI RESTE OUVERT ─────────────────────────────────
-- Les trois pages de Cigar Inspector répondent 403 : non lues, non citées.
-- vegassantiago.com présente le certificat d'un autre hôte : retiré de la
-- source. LH Premium Cigar sort de l'atelier (Cigar Coop, 25 novembre
-- 2024) mais n'a pas de fiche. Atabey (« le cigare le plus cher de cet
-- atlas ») et Byron (« des prix qui le placent tout en haut du marché »)
-- gardent des mots de prix et de rang que les règles écartent : hors de
-- cette migration, qui ne touche que ce que l'atelier contredit.
--
-- Rejouable : chaque remplacement est gardé par la présence du texte
-- ancien (comparé octet par octet), la gamme est relue en base et réécrite
-- en littéral dans chaque langue, les sceaux repassent à `machine`.
-- ════════════════════════════════════════════════════════

-- ── Vegas de Santiago ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Vegas de Santiago est ce qui dément la formule — elle cultive ce qu''elle roule.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Vegas de Santiago est ce qui dément la formule — elle cultive ce qu''elle roule.', 'La maison Vegas de Santiago écrit cultiver une part de ses feuilles et importer le reste.'), `history`),
  `history_en` = IF(LOCATE(CAST('Vegas de Santiago is what contradicts the formula — it grows what it rolls.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Vegas de Santiago is what contradicts the formula — it grows what it rolls.', 'The Vegas de Santiago house writes that it grows part of its leaf and imports the rest.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Vegas de Santiago es lo que desmiente la fórmula — cultiva lo que lía.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Vegas de Santiago es lo que desmiente la fórmula — cultiva lo que lía.', 'La casa Vegas de Santiago escribe que cultiva una parte de sus hojas e importa el resto.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Vegas de Santiago ist das, was die Formel widerlegt — es baut an, was es rollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Vegas de Santiago ist das, was die Formel widerlegt — es baut an, was es rollt.', 'Das Haus Vegas de Santiago schreibt, es baue einen Teil seiner Blätter an und importiere den Rest.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Vegas de Santiago 正是推翻这一说法的存在——它种自己所卷的烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Vegas de Santiago 正是推翻这一说法的存在——它种自己所卷的烟叶。', 'Vegas de Santiago 公司写道，自己种植一部分烟叶，其余进口。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أمّا فيغاس دي سانتياغو فهي ما يكذّب هذه الصيغة — إذ تزرع ما تلفّه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أمّا فيغاس دي سانتياغو فهي ما يكذّب هذه الصيغة — إذ تزرع ما تلفّه.', 'تكتب دار Vegas de Santiago أنّها تزرع جزءًا من أوراقها وتستورد الباقي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Ses champs sont à Santiago de Puriscal, dans les montagnes volcaniques au sud-ouest de San José, à plus de mille cent mètres. On y plante du tabac depuis plus de quatre-vingts ans. L''altitude tient lieu de traitement : la maison explique qu''elle se passe de pesticides parce que les ravageurs ne montent pas si haut.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Ses champs sont à Santiago de Puriscal, dans les montagnes volcaniques au sud-ouest de San José, à plus de mille cent mètres. On y plante du tabac depuis plus de quatre-vingts ans. L''altitude tient lieu de traitement : la maison explique qu''elle se passe de pesticides parce que les ravageurs ne montent pas si haut.', 'La maison écrit que ses familles cultivent du tabac dans les montagnes volcaniques de Santiago de Puriscal, au sud-ouest de San José, depuis plus de quatre-vingts ans (à plus de mille cent mètres, dit Zechbauer), et qu''elle se passe de pesticides à cette altitude. La Nación écrivait en 2011 que la production de tabac avait cessé à Puriscal à la récolte 1997-1998 et que l''atelier faisait venir sa matière première du Pérou, d''Équateur et du Nicaragua, 15 % seulement s''achetant à Pérez Zeledón.'), `history`),
  `history_en` = IF(LOCATE(CAST('Its fields are at Santiago de Puriscal, in the volcanic mountains south-west of San José, above eleven hundred metres. Tobacco has been planted there for more than eighty years. Altitude serves as treatment: the house explains that it does without pesticides because the pests do not climb that high.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Its fields are at Santiago de Puriscal, in the volcanic mountains south-west of San José, above eleven hundred metres. Tobacco has been planted there for more than eighty years. Altitude serves as treatment: the house explains that it does without pesticides because the pests do not climb that high.', 'The house writes that its families have grown tobacco in the volcanic mountains of Santiago de Puriscal, south-west of San José, for more than eighty years (above eleven hundred metres, says Zechbauer), and that it does without pesticides at that altitude. La Nación wrote in 2011 that tobacco production had ceased in Puriscal with the 1997-1998 harvest and that the workshop brought in its raw material from Peru, Ecuador and Nicaragua, only 15% being bought in Pérez Zeledón.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Sus campos están en Santiago de Puriscal, en las montañas volcánicas al suroeste de San José, a más de mil cien metros. Allí se planta tabaco desde hace más de ochenta años. La altitud hace las veces de tratamiento: la casa explica que prescinde de pesticidas porque las plagas no suben tan alto.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Sus campos están en Santiago de Puriscal, en las montañas volcánicas al suroeste de San José, a más de mil cien metros. Allí se planta tabaco desde hace más de ochenta años. La altitud hace las veces de tratamiento: la casa explica que prescinde de pesticidas porque las plagas no suben tan alto.', 'La casa escribe que sus familias cultivan tabaco en las montañas volcánicas de Santiago de Puriscal, al suroeste de San José, desde hace más de ochenta años (a más de mil cien metros, dice Zechbauer), y que prescinde de pesticidas a esa altitud. La Nación escribía en 2011 que la producción de tabaco había cesado en Puriscal en la cosecha 1997-1998 y que el taller hacía venir su materia prima de Perú, Ecuador y Nicaragua, comprándose en Pérez Zeledón solo el 15 %.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Seine Felder liegen in Santiago de Puriscal, in den vulkanischen Bergen südwestlich von San José, auf über elfhundert Metern. Seit mehr als achtzig Jahren wird dort Tabak gepflanzt. Die Höhe ersetzt die Behandlung: Das Haus erklärt, es komme ohne Pestizide aus, weil die Schädlinge nicht so hoch steigen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Seine Felder liegen in Santiago de Puriscal, in den vulkanischen Bergen südwestlich von San José, auf über elfhundert Metern. Seit mehr als achtzig Jahren wird dort Tabak gepflanzt. Die Höhe ersetzt die Behandlung: Das Haus erklärt, es komme ohne Pestizide aus, weil die Schädlinge nicht so hoch steigen.', 'Das Haus schreibt, dass seine Familien in den vulkanischen Bergen von Santiago de Puriscal, südwestlich von San José, seit mehr als achtzig Jahren Tabak anbauen (auf über elfhundert Metern, sagt Zechbauer) und dass es in dieser Höhe ohne Pestizide auskommt. La Nación schrieb 2011, die Tabakproduktion habe in Puriscal mit der Ernte 1997-1998 aufgehört und die Werkstatt lasse ihren Rohstoff aus Peru, Ecuador und Nicaragua kommen, wobei nur 15 % in Pérez Zeledón gekauft würden.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它的田地在圣何塞西南火山群山中的圣地亚哥-德普里斯卡尔，海拔一千一百米以上。此地种植烟草已逾八十年。海拔本身即是处理之法：该号称，虫害爬不了这么高，因此无须农药。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它的田地在圣何塞西南火山群山中的圣地亚哥-德普里斯卡尔，海拔一千一百米以上。此地种植烟草已逾八十年。海拔本身即是处理之法：该号称，虫害爬不了这么高，因此无须农药。', '该号写道，旗下各家族在圣何塞西南火山群山中的圣地亚哥-德普里斯卡尔种植烟草已逾八十年（据 Zechbauer 称，海拔一千一百米以上），且在这一海拔高度上无须农药。La Nación 在2011年写道，普里斯卡尔的烟草生产止于1997-1998年度的收获，作坊的原料从秘鲁、厄瓜多尔和尼加拉瓜运来，仅15%购自 Pérez Zeledón。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('حقولها في سانتياغو دي بوريسكال، في الجبال البركانية جنوب غربي سان خوسيه، على ارتفاع يتجاوز ألفًا ومئة متر. ويُزرع التبغ هناك منذ أكثر من ثمانين سنة. والارتفاع يقوم مقام المعالجة: تقول الدار إنّها تستغني عن المبيدات لأنّ الآفات لا تصعد إلى هذا العلوّ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'حقولها في سانتياغو دي بوريسكال، في الجبال البركانية جنوب غربي سان خوسيه، على ارتفاع يتجاوز ألفًا ومئة متر. ويُزرع التبغ هناك منذ أكثر من ثمانين سنة. والارتفاع يقوم مقام المعالجة: تقول الدار إنّها تستغني عن المبيدات لأنّ الآفات لا تصعد إلى هذا العلوّ.', 'تكتب الدار أنّ عائلاتها تزرع التبغ في الجبال البركانية من سانتياغو دي بوريسكال، جنوب غربي سان خوسيه، منذ أكثر من ثمانين سنة (على ارتفاع يتجاوز ألفًا ومئة متر، بحسب Zechbauer)، وأنّها تستغني عن المبيدات عند هذا الارتفاع. وكتبت La Nación سنة 2011 أنّ إنتاج التبغ توقّف في بوريسكال عند حصاد 1997-1998، وأنّ الورشة كانت تستقدم مادتها الأولية من بيرو والإكوادور ونيكاراغوا، ولا يُشترى من Pérez Zeledón سوى 15%.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Marc Niehaus l''a fondée. Aucune source consultable n''en donne l''année, et cette fiche préfère le dire que l''inventer — la même règle que pour Kolumbus aux Canaries. Un maître cubain, Luis Santana Lamas, y a apporté la manière de traiter la feuille et de rouler ; la maison le nomme, et son prénom est resté sur une gamme.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Marc Niehaus l''a fondée. Aucune source consultable n''en donne l''année, et cette fiche préfère le dire que l''inventer — la même règle que pour Kolumbus aux Canaries. Un maître cubain, Luis Santana Lamas, y a apporté la manière de traiter la feuille et de rouler ; la maison le nomme, et son prénom est resté sur une gamme.', 'Qui l''a fondée se lit de deux façons : Marc Niehaus seul, écrit Casagranda, son distributeur allemand ; les familles Niehaus et Guzmán ensemble, écrit Cigarrspecialisten, détaillant suédois. La maison, sans nommer de fondateur, présente Marc Niehaus comme partenaire et responsable des ventes internationales. Casagranda date de 1997 la manufacture familiale Tabacos de Costa Rica ; un entretien avec Marc Niehaus, publié sur vdg-cigars.com, situe en 1998 l''ouverture de la fabrique ; aucune source citée ne donne l''année de la marque.'), `history`),
  `history_en` = IF(LOCATE(CAST('Marc Niehaus founded it. No consultable source gives the year, and this entry prefers to say so rather than invent it — the same rule as for Kolumbus in the Canaries. A Cuban master, Luis Santana Lamas, brought the way of curing the leaf and of rolling; the house names him, and his first name has stayed on a line.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Marc Niehaus founded it. No consultable source gives the year, and this entry prefers to say so rather than invent it — the same rule as for Kolumbus in the Canaries. A Cuban master, Luis Santana Lamas, brought the way of curing the leaf and of rolling; the house names him, and his first name has stayed on a line.', 'Who founded it can be read in two ways: Marc Niehaus alone, writes Casagranda, its German distributor; the Niehaus and Guzmán families together, writes Cigarrspecialisten, a Swedish retailer. The house, without naming a founder, presents Marc Niehaus as a partner and head of international sales. Casagranda dates the family factory Tabacos de Costa Rica to 1997; an interview with Marc Niehaus, published on vdg-cigars.com, places the opening of the factory in 1998; no cited source gives the year of the brand.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Marc Niehaus la fundó. Ninguna fuente consultable da el año, y esta ficha prefiere decirlo a inventarlo — la misma regla que para Kolumbus en Canarias. Un maestro cubano, Luis Santana Lamas, aportó la manera de curar la hoja y de liar; la casa lo nombra, y su nombre de pila quedó en una línea.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Marc Niehaus la fundó. Ninguna fuente consultable da el año, y esta ficha prefiere decirlo a inventarlo — la misma regla que para Kolumbus en Canarias. Un maestro cubano, Luis Santana Lamas, aportó la manera de curar la hoja y de liar; la casa lo nombra, y su nombre de pila quedó en una línea.', 'Quién la fundó se lee de dos maneras: Marc Niehaus solo, escribe Casagranda, su distribuidor alemán; las familias Niehaus y Guzmán juntas, escribe Cigarrspecialisten, minorista sueco. La casa, sin nombrar a ningún fundador, presenta a Marc Niehaus como socio y responsable de las ventas internacionales. Casagranda fecha en 1997 la fábrica familiar Tabacos de Costa Rica; una entrevista con Marc Niehaus, publicada en vdg-cigars.com, sitúa en 1998 la apertura de la fábrica; ninguna fuente citada da el año de la marca.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Marc Niehaus hat es gegründet. Keine einsehbare Quelle nennt das Jahr, und dieser Eintrag sagt das lieber, als es zu erfinden — dieselbe Regel wie bei Kolumbus auf den Kanaren. Ein kubanischer Meister, Luis Santana Lamas, brachte die Art, das Blatt zu behandeln und zu rollen; das Haus nennt ihn, und sein Vorname ist auf einer Linie geblieben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Marc Niehaus hat es gegründet. Keine einsehbare Quelle nennt das Jahr, und dieser Eintrag sagt das lieber, als es zu erfinden — dieselbe Regel wie bei Kolumbus auf den Kanaren. Ein kubanischer Meister, Luis Santana Lamas, brachte die Art, das Blatt zu behandeln und zu rollen; das Haus nennt ihn, und sein Vorname ist auf einer Linie geblieben.', 'Wer es gegründet hat, lässt sich auf zwei Arten lesen: Marc Niehaus allein, schreibt Casagranda, sein deutscher Distributor; die Familien Niehaus und Guzmán gemeinsam, schreibt Cigarrspecialisten, ein schwedischer Händler. Das Haus nennt keinen Gründer und stellt Marc Niehaus als Partner und Verantwortlichen für den internationalen Vertrieb vor. Casagranda datiert die Familienfabrik Tabacos de Costa Rica auf 1997; ein Interview mit Marc Niehaus, veröffentlicht auf vdg-cigars.com, setzt die Eröffnung der Fabrik auf 1998 an; keine zitierte Quelle nennt das Jahr der Marke.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('创立者是马克·尼豪斯。可查的资料均未给出年份，本词条宁可直说，也不愿臆造——与加那利群岛的 Kolumbus 同一准则。一位古巴大师路易斯·桑塔纳·拉马斯将处理烟叶与卷制的手法带到此地；该号点出他的名字，而他的名也留在了一个系列上。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '创立者是马克·尼豪斯。可查的资料均未给出年份，本词条宁可直说，也不愿臆造——与加那利群岛的 Kolumbus 同一准则。一位古巴大师路易斯·桑塔纳·拉马斯将处理烟叶与卷制的手法带到此地；该号点出他的名字，而他的名也留在了一个系列上。', '创立者有两种说法：马克·尼豪斯一人创立，据其德国经销商 Casagranda 所写；尼豪斯与古斯曼两个家族共同创立，据瑞典零售商 Cigarrspecialisten 所写。该号没有点出创始人，而将马克·尼豪斯介绍为合伙人兼国际销售负责人。Casagranda 把家族工厂 Tabacos de Costa Rica 追溯到1997年；vdg-cigars.com 上发表的一篇对马克·尼豪斯的访谈把工厂的开业定在1998年；所引资料均未给出该品牌的年份。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أسّسها مارك نيهاوس. ولا يذكر أيّ مصدر متاح سنةَ التأسيس، وتفضّل هذه البطاقة قول ذلك على اختلاقه — وهي القاعدة نفسها المتّبعة مع كولومبوس في جزر الكناري. وقد نقل إليها معلّم كوبي، لويس سانتانا لاماس، طريقةَ معالجة الورقة واللفّ؛ تذكره الدار باسمه، وقد بقي اسمه الأوّل على أحد خطوطها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أسّسها مارك نيهاوس. ولا يذكر أيّ مصدر متاح سنةَ التأسيس، وتفضّل هذه البطاقة قول ذلك على اختلاقه — وهي القاعدة نفسها المتّبعة مع كولومبوس في جزر الكناري. وقد نقل إليها معلّم كوبي، لويس سانتانا لاماس، طريقةَ معالجة الورقة واللفّ؛ تذكره الدار باسمه، وقد بقي اسمه الأوّل على أحد خطوطها.', 'مَن أسّسها يُقرأ على وجهين: مارك نيهاوس وحده، تكتب Casagranda، موزّعها الألماني؛ وعائلتا نيهاوس وغوسمان معًا، تكتب Cigarrspecialisten، تاجر تجزئة سويدي. أمّا الدار فمن دون أن تسمّي مؤسّسًا تقدّم مارك نيهاوس شريكًا ومسؤولًا عن المبيعات الدولية. وتؤرّخ Casagranda المصنع العائلي Tabacos de Costa Rica بسنة 1997؛ ويضع حوار مع مارك نيهاوس، نُشر على vdg-cigars.com، افتتاح المصنع في سنة 1998؛ ولا يذكر أيّ مصدر مستشهَد به سنة العلامة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Elle fait ses lignes — Chaman, Reserva, Don Luis, Secretos del Maestro — et elle roule aussi pour d''autres : des bagues de détaillants européens sortent de cet atelier, dont celles de Zechbauer, la maison de Munich. Chaman, que le recensement de cet atlas prenait pour une maison à part, est l''une de ses gammes.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Elle fait ses lignes — Chaman, Reserva, Don Luis, Secretos del Maestro — et elle roule aussi pour d''autres : des bagues de détaillants européens sortent de cet atelier, dont celles de Zechbauer, la maison de Munich. Chaman, que le recensement de cet atlas prenait pour une maison à part, est l''une de ses gammes.', 'Elle fait ses lignes — Chaman, Reserva, Don Luis, Secretos del Maestro, El Puro — et l''atelier roule aussi pour d''autres, dont les Zechbauer Royales de la maison de Munich. Chaman est l''une de ses gammes.'), `history`),
  `history_en` = IF(LOCATE(CAST('It makes its own lines — Chaman, Reserva, Don Luis, Secretos del Maestro — and it also rolls for others: bands of European retailers come out of this workshop, among them those of Zechbauer, the Munich house. Chaman, which this atlas''s census took for a separate house, is one of its lines.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'It makes its own lines — Chaman, Reserva, Don Luis, Secretos del Maestro — and it also rolls for others: bands of European retailers come out of this workshop, among them those of Zechbauer, the Munich house. Chaman, which this atlas''s census took for a separate house, is one of its lines.', 'It makes its own lines — Chaman, Reserva, Don Luis, Secretos del Maestro, El Puro — and the workshop also rolls for others, among them the Zechbauer Royales of the Munich house. Chaman is one of its lines.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Hace sus propias líneas — Chaman, Reserva, Don Luis, Secretos del Maestro — y lía también para otros: de este taller salen anillas de minoristas europeos, entre ellas las de Zechbauer, la casa de Múnich. Chaman, que el censo de este atlas tomaba por una casa aparte, es una de sus líneas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Hace sus propias líneas — Chaman, Reserva, Don Luis, Secretos del Maestro — y lía también para otros: de este taller salen anillas de minoristas europeos, entre ellas las de Zechbauer, la casa de Múnich. Chaman, que el censo de este atlas tomaba por una casa aparte, es una de sus líneas.', 'Hace sus propias líneas — Chaman, Reserva, Don Luis, Secretos del Maestro, El Puro — y el taller lía también para otros, entre ellos los Zechbauer Royales de la casa de Múnich. Chaman es una de sus líneas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Es fertigt eigene Linien — Chaman, Reserva, Don Luis, Secretos del Maestro — und rollt auch für andere: Banderolen europäischer Händler verlassen diese Werkstatt, darunter die von Zechbauer, dem Münchner Haus. Chaman, das die Bestandsaufnahme dieses Atlas für ein eigenes Haus hielt, ist eine seiner Linien.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Es fertigt eigene Linien — Chaman, Reserva, Don Luis, Secretos del Maestro — und rollt auch für andere: Banderolen europäischer Händler verlassen diese Werkstatt, darunter die von Zechbauer, dem Münchner Haus. Chaman, das die Bestandsaufnahme dieses Atlas für ein eigenes Haus hielt, ist eine seiner Linien.', 'Es fertigt eigene Linien — Chaman, Reserva, Don Luis, Secretos del Maestro, El Puro — und die Werkstatt rollt auch für andere, darunter die Zechbauer Royales des Münchner Hauses. Chaman ist eine seiner Linien.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它做自己的系列——Chaman、Reserva、Don Luis、Secretos del Maestro——也为别人卷制：欧洲零售商的烟标出自这家作坊，其中包括慕尼黑老号 Zechbauer 的。Chaman 曾被本图集的普查误作独立老号，其实是它的一个系列。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它做自己的系列——Chaman、Reserva、Don Luis、Secretos del Maestro——也为别人卷制：欧洲零售商的烟标出自这家作坊，其中包括慕尼黑老号 Zechbauer 的。Chaman 曾被本图集的普查误作独立老号，其实是它的一个系列。', '它做自己的系列——Chaman、Reserva、Don Luis、Secretos del Maestro、El Puro——作坊也为别人卷制，其中包括慕尼黑老号的 Zechbauer Royales。Chaman 是它的一个系列。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تصنع خطوطها الخاصة — تشامان، ورِسِرفا، ودون لويس، وسِكريتوس ديل مايسترو — وتلفّ أيضًا لغيرها: فمن هذه الورشة تخرج أطواق تجّار أوروبيين، منها أطواق تسيشباور، الدار الميونيخية. وتشامان، التي حسبها إحصاءُ هذا الأطلس دارًا مستقلّة، إنّما هي أحد خطوطها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تصنع خطوطها الخاصة — تشامان، ورِسِرفا، ودون لويس، وسِكريتوس ديل مايسترو — وتلفّ أيضًا لغيرها: فمن هذه الورشة تخرج أطواق تجّار أوروبيين، منها أطواق تسيشباور، الدار الميونيخية. وتشامان، التي حسبها إحصاءُ هذا الأطلس دارًا مستقلّة، إنّما هي أحد خطوطها.', 'تصنع خطوطها الخاصة — Chaman وReserva وDon Luis وSecretos del Maestro وEl Puro — وتلفّ الورشة أيضًا لغيرها، ومنها Zechbauer Royales التابعة للدار الميونيخية. وChaman أحد خطوطها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''atelier a changé de raison sociale et travaille aujourd''hui sous le nom de Tabacos de Costa Rica S.A. Zechbauer présente Olman León Guzmán comme le chef de la fabrique ; Casdagli le nomme maître assembleur et écrit que sa coopération avec « Tabacos de Costa Rica S.A., alors connue sous le nom de Vegas Santiago » a commencé en 2012. C''est ici, et non ailleurs au Costa Rica, que se roule la ligne Villa Casdagli.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''atelier a changé de raison sociale et travaille aujourd''hui sous le nom de Tabacos de Costa Rica S.A. Zechbauer présente Olman León Guzmán comme le chef de la fabrique ; Casdagli le nomme maître assembleur et écrit que sa coopération avec « Tabacos de Costa Rica S.A., alors connue sous le nom de Vegas Santiago » a commencé en 2012. C''est ici, et non ailleurs au Costa Rica, que se roule la ligne Villa Casdagli.', 'L''atelier travaille sous le nom de Tabacos de Costa Rica S.A. : La Nación nommait en 2011 Olman León propriétaire de la fabrique, et Cigar Coop nomme en 2019 Andrés León propriétaire et exploitant. Zechbauer présente Olman León Guzmán comme chef de la manufacture ; Casdagli le nomme maître assembleur et écrit que sa coopération avec « Tabacos de Costa Rica S.A., alors connue sous le nom de Vegas Santiago » a commencé en 2012. La ligne Villa Casdagli s''y roule.'), `history`),
  `history_en` = IF(LOCATE(CAST('The workshop has changed its trading name and works today as Tabacos de Costa Rica S.A. Zechbauer presents Olman León Guzmán as the head of the factory; Casdagli calls him master blender and writes that its cooperation with "Tabacos de Costa Rica S.A., then known as Vegas Santiago" began in 2012. It is here, and nowhere else in Costa Rica, that the Villa Casdagli line is rolled.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The workshop has changed its trading name and works today as Tabacos de Costa Rica S.A. Zechbauer presents Olman León Guzmán as the head of the factory; Casdagli calls him master blender and writes that its cooperation with "Tabacos de Costa Rica S.A., then known as Vegas Santiago" began in 2012. It is here, and nowhere else in Costa Rica, that the Villa Casdagli line is rolled.', 'The workshop works under the name of Tabacos de Costa Rica S.A.: La Nación named Olman León in 2011 as owner of the factory, and Cigar Coop names Andrés León in 2019 as owner and operator. Zechbauer presents Olman León Guzmán as the head of the factory; Casdagli calls him master blender and writes that its cooperation with “Tabacos de Costa Rica S.A., then known as Vegas Santiago” began in 2012. The Villa Casdagli line is rolled there.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El taller cambió de razón social y trabaja hoy como Tabacos de Costa Rica S.A. Zechbauer presenta a Olman León Guzmán como jefe de la fábrica; Casdagli lo llama maestro ligador y escribe que su cooperación con «Tabacos de Costa Rica S.A., entonces conocida como Vegas Santiago» comenzó en 2012. Es aquí, y no en otro lugar de Costa Rica, donde se lía la línea Villa Casdagli.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El taller cambió de razón social y trabaja hoy como Tabacos de Costa Rica S.A. Zechbauer presenta a Olman León Guzmán como jefe de la fábrica; Casdagli lo llama maestro ligador y escribe que su cooperación con «Tabacos de Costa Rica S.A., entonces conocida como Vegas Santiago» comenzó en 2012. Es aquí, y no en otro lugar de Costa Rica, donde se lía la línea Villa Casdagli.', 'El taller trabaja bajo el nombre de Tabacos de Costa Rica S.A.: La Nación nombraba en 2011 a Olman León propietario de la fábrica, y Cigar Coop nombra en 2019 a Andrés León propietario y operador. Zechbauer presenta a Olman León Guzmán como jefe de la fábrica; Casdagli lo llama maestro ligador y escribe que su cooperación con «Tabacos de Costa Rica S.A., entonces conocida como Vegas Santiago» comenzó en 2012. La línea Villa Casdagli se lía allí.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Werkstatt hat ihren Firmennamen gewechselt und arbeitet heute als Tabacos de Costa Rica S.A. Zechbauer stellt Olman León Guzmán als Leiter der Fabrik vor; Casdagli nennt ihn Master Blender und schreibt, die Zusammenarbeit mit „Tabacos de Costa Rica S.A., damals bekannt als Vegas Santiago" habe 2012 begonnen. Hier, und nirgendwo sonst in Costa Rica, wird die Linie Villa Casdagli gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Werkstatt hat ihren Firmennamen gewechselt und arbeitet heute als Tabacos de Costa Rica S.A. Zechbauer stellt Olman León Guzmán als Leiter der Fabrik vor; Casdagli nennt ihn Master Blender und schreibt, die Zusammenarbeit mit „Tabacos de Costa Rica S.A., damals bekannt als Vegas Santiago" habe 2012 begonnen. Hier, und nirgendwo sonst in Costa Rica, wird die Linie Villa Casdagli gerollt.', 'Die Werkstatt arbeitet unter dem Namen Tabacos de Costa Rica S.A.: La Nación nannte 2011 Olman León als Eigentümer der Fabrik, und Cigar Coop nennt 2019 Andrés León als Eigentümer und Betreiber. Zechbauer stellt Olman León Guzmán als Leiter der Fabrik vor; Casdagli nennt ihn Master Blender und schreibt, die Zusammenarbeit mit „Tabacos de Costa Rica S.A., damals bekannt als Vegas Santiago“ habe 2012 begonnen. Die Linie Villa Casdagli wird dort gerollt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('作坊已更改商号，如今以 Tabacos de Costa Rica S.A. 之名经营。Zechbauer 称奥尔曼·莱昂·古斯曼为厂长；Casdagli 称他为调配大师，并写道与「Tabacos de Costa Rica S.A.，当时名为 Vegas Santiago」的合作始于2012年。Villa Casdagli 系列正是在这里卷制，而非哥斯达黎加的其他地方。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '作坊已更改商号，如今以 Tabacos de Costa Rica S.A. 之名经营。Zechbauer 称奥尔曼·莱昂·古斯曼为厂长；Casdagli 称他为调配大师，并写道与「Tabacos de Costa Rica S.A.，当时名为 Vegas Santiago」的合作始于2012年。Villa Casdagli 系列正是在这里卷制，而非哥斯达黎加的其他地方。', '作坊以 Tabacos de Costa Rica S.A. 之名经营：La Nación 在2011年称奥尔曼·莱昂为工厂业主，Cigar Coop 在2019年称安德烈斯·莱昂为业主兼经营者。Zechbauer 称奥尔曼·莱昂·古斯曼为厂长；Casdagli 称他为调配大师，并写道与「Tabacos de Costa Rica S.A.，当时名为 Vegas Santiago」的合作始于2012年。Villa Casdagli 系列就在这里卷制。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وقد غيّرت الورشة اسمها التجاري، وهي تعمل اليوم باسم Tabacos de Costa Rica S.A. يقدّم تسيشباور أولمان ليون غوسمان بوصفه رئيس المصنع؛ وتسمّيه كاسداغلي كبير المزّاجين وتكتب أنّ تعاونها مع «Tabacos de Costa Rica S.A.، المعروفة آنذاك باسم فيغاس سانتياغو» بدأ سنة 2012. وهنا، لا في مكان آخر من كوستاريكا، يُلفّ خط Villa Casdagli.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وقد غيّرت الورشة اسمها التجاري، وهي تعمل اليوم باسم Tabacos de Costa Rica S.A. يقدّم تسيشباور أولمان ليون غوسمان بوصفه رئيس المصنع؛ وتسمّيه كاسداغلي كبير المزّاجين وتكتب أنّ تعاونها مع «Tabacos de Costa Rica S.A.، المعروفة آنذاك باسم فيغاس سانتياغو» بدأ سنة 2012. وهنا، لا في مكان آخر من كوستاريكا، يُلفّ خط Villa Casdagli.', 'تعمل الورشة باسم Tabacos de Costa Rica S.A.: سمّت La Nación سنة 2011 أولمان ليون مالكًا للمصنع، وتسمّي Cigar Coop سنة 2019 أندريس ليون مالكًا ومشغّلًا. ويقدّم Zechbauer أولمان ليون غوسمان بوصفه رئيس المصنع؛ وتسمّيه Casdagli كبير المزّاجين وتكتب أنّ تعاونها مع «Tabacos de Costa Rica S.A.، المعروفة آنذاك باسم Vegas Santiago» بدأ سنة 2012. ويُلفّ في هذه الورشة خط Villa Casdagli.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Une troisième marque de cet atlas sort du même atelier : MBombay, la maison de Mel Shah, Bombay Tobak, y fait rouler toutes ses lignes depuis 2014. Puriscal roule donc pour Casdagli, Zechbauer et Bombay Tobak — et pour elle-même.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Une troisième marque de cet atlas sort du même atelier : MBombay, la maison de Mel Shah, Bombay Tobak, y fait rouler toutes ses lignes depuis 2014. Puriscal roule donc pour Casdagli, Zechbauer et Bombay Tobak — et pour elle-même.', 'D''autres marques de cet atlas sortent du même atelier : Selected Tobacco (Atabey, Bandolero, Byron) et Bombay Tobak, d''après Cigar Coop ; Malekö et Skull 77, que des détaillants disent fabriquées par Tabacos de Costa Rica S.A.'), `history`),
  `history_en` = IF(LOCATE(CAST('A third brand of this atlas comes out of the same workshop: MBombay, Mel Shah''s house, Bombay Tobak, has had all its lines rolled there since 2014. Puriscal thus rolls for Casdagli, Zechbauer and Bombay Tobak — and for itself.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'A third brand of this atlas comes out of the same workshop: MBombay, Mel Shah''s house, Bombay Tobak, has had all its lines rolled there since 2014. Puriscal thus rolls for Casdagli, Zechbauer and Bombay Tobak — and for itself.', 'Other brands of this atlas come out of the same workshop: Selected Tobacco (Atabey, Bandolero, Byron) and Bombay Tobak, according to Cigar Coop; Malekö and Skull 77, which retailers say are made by Tabacos de Costa Rica S.A.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Una tercera marca de este atlas sale del mismo taller: MBombay, la casa de Mel Shah, Bombay Tobak, hace liar allí todas sus líneas desde 2014. Puriscal lía pues para Casdagli, Zechbauer y Bombay Tobak — y para sí misma.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Una tercera marca de este atlas sale del mismo taller: MBombay, la casa de Mel Shah, Bombay Tobak, hace liar allí todas sus líneas desde 2014. Puriscal lía pues para Casdagli, Zechbauer y Bombay Tobak — y para sí misma.', 'Otras marcas de este atlas salen del mismo taller: Selected Tobacco (Atabey, Bandolero, Byron) y Bombay Tobak, según Cigar Coop; Malekö y Skull 77, que, según unos minoristas, fabrica Tabacos de Costa Rica S.A.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Eine dritte Marke dieses Atlas kommt aus derselben Werkstatt: MBombay, das Haus von Mel Shah, Bombay Tobak, lässt dort seit 2014 alle seine Linien rollen. Puriscal rollt also für Casdagli, Zechbauer und Bombay Tobak — und für sich selbst.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Eine dritte Marke dieses Atlas kommt aus derselben Werkstatt: MBombay, das Haus von Mel Shah, Bombay Tobak, lässt dort seit 2014 alle seine Linien rollen. Puriscal rollt also für Casdagli, Zechbauer und Bombay Tobak — und für sich selbst.', 'Weitere Marken dieses Atlas kommen aus derselben Werkstatt: Selected Tobacco (Atabey, Bandolero, Byron) und Bombay Tobak, nach Angaben von Cigar Coop; Malekö und Skull 77, die nach Aussage von Händlern von Tabacos de Costa Rica S.A. hergestellt werden.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集的第三个品牌出自同一作坊：梅尔·沙阿的公司 Bombay Tobak 旗下的 MBombay，自2014年起所有系列都在这里卷制。普里斯卡尔因此为 Casdagli、Zechbauer 与 Bombay Tobak 卷制——也为自己。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集的第三个品牌出自同一作坊：梅尔·沙阿的公司 Bombay Tobak 旗下的 MBombay，自2014年起所有系列都在这里卷制。普里斯卡尔因此为 Casdagli、Zechbauer 与 Bombay Tobak 卷制——也为自己。', '本图集的另一些品牌出自同一作坊：Selected Tobacco（Atabey、Bandolero、Byron）与 Bombay Tobak，据 Cigar Coop 所述；Malekö 与 Skull 77，据一些零售商所称由 Tabacos de Costa Rica S.A. 制造。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('علامةٌ ثالثة من هذا الأطلس تخرج من الورشة نفسها: MBombay، دار ميل شاه، Bombay Tobak، تُلفّ فيها كلّ خطوطها منذ 2014. فبوريسكال تلفّ إذن لِـCasdagli وZechbauer وBombay Tobak — ولنفسها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'علامةٌ ثالثة من هذا الأطلس تخرج من الورشة نفسها: MBombay، دار ميل شاه، Bombay Tobak، تُلفّ فيها كلّ خطوطها منذ 2014. فبوريسكال تلفّ إذن لِـCasdagli وZechbauer وBombay Tobak — ولنفسها.', 'علاماتٌ أخرى من هذا الأطلس تخرج من الورشة نفسها: Selected Tobacco (Atabey وBandolero وByron) وBombay Tobak، بحسب Cigar Coop؛ أمّا Malekö وSkull 77 فيقول بعض تجّار التجزئة إنّ Tabacos de Costa Rica S.A. تصنعهما.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

UPDATE `brands` SET
  `founded` = 'Non précisée — Guzmán et Niehaus, Puriscal',
  `factory` = 'Santiago de Puriscal, San José — Tabacos de Costa Rica S.A., alors connue sous le nom de Vegas Santiago (Casdagli) ; propriétaires nommés : Olman León (2011), Andrés León (2019)',
  `gamme` = '[{"name":"Chaman","color":"#4A5D3A","force":"Medium-Full","story":"Le nom veut dire chaman ; le site de la maison l''appelle aussi El Mystico. Il donne une cape Connecticut d''Équateur, un liant du Nicaragua et une tripe du Costa Rica et du Nicaragua ; une autre page de la maison donne au liant le Costa Rica et le Nicaragua.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut d''Équateur"},{"name":"Reserva","color":"#6B4226","force":"Medium","story":"La maison écrit que ses tabacs mûrissent au moins trois ans avant le roulage et que ses cigares reposent trois mois en magasin climatisé, Zechbauer précisant une chambre de cèdre ; ces délais valent pour toutes ses lignes, et ses pages ne donnent pas les origines de Reserva.","vitolas":["Robusto","Toro"],"wrapper":"Non divulguée"},{"name":"Don Luis","color":"#8B5A2B","force":"Medium-Full","story":"Gold Label sur le site de la maison, qui donne une cape Connecticut d''Équateur, un liant d''Équateur et une tripe des Caraïbes. Casagranda nomme Don Luis Santana Lamas, ancien chef de production de l''usine H. Upmann, à Cuba, et Zechbauer écrit qu''il a travaillé à l''atelier jusqu''à sa mort.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Connecticut d''Équateur"},{"name":"El Puro (Red Label)","color":"#6B4423","force":null,"story":"Édition spéciale que la maison dit entièrement faite de tabac cultivé dans ses propres champs, dans les montagnes volcaniques de Santiago de Puriscal : cape, liant et tripe du Costa Rica.","vitolas":[],"wrapper":"Costa Rica, dit la maison"}]',
  `gamme_en` = '[{"name":"Chaman","color":"#4A5D3A","force":"Medium-Full","story":"The name means shaman; the house''s website also calls it El Mystico. The site gives a Connecticut wrapper from Ecuador, a binder from Nicaragua and a filler from Costa Rica and Nicaragua; another page of the house gives Costa Rica and Nicaragua for the binder.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Ecuadorian Connecticut"},{"name":"Reserva","color":"#6B4226","force":"Medium","story":"The house writes that its tobaccos mature at least three years before rolling and that its cigars rest three months in an air-conditioned storeroom, Zechbauer specifying a cedar room; these times apply to all its lines, and its pages do not give the origins of Reserva.","vitolas":["Robusto","Toro"],"wrapper":"Not disclosed"},{"name":"Don Luis","color":"#8B5A2B","force":"Medium-Full","story":"Gold Label on the house''s website, which gives a Connecticut wrapper from Ecuador, a binder from Ecuador and a filler from the Caribbean. Casagranda names Don Luis Santana Lamas, former head of production at the H. Upmann factory in Cuba, and Zechbauer writes that he worked at the workshop until his death.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Ecuadorian Connecticut"},{"name":"El Puro (Red Label)","color":"#6B4423","force":null,"story":"Special edition that the house says is made entirely of tobacco grown in its own fields, in the volcanic mountains of Santiago de Puriscal: wrapper, binder and filler from Costa Rica.","vitolas":[],"wrapper":"Costa Rica, says the house"}]',
  `gamme_es` = '[{"name":"Chaman","color":"#4A5D3A","force":"Medium-Full","story":"El nombre significa chamán; el sitio de la casa lo llama también El Mystico. El sitio da una capa Connecticut de Ecuador, un capote de Nicaragua y una tripa de Costa Rica y Nicaragua; otra página de la casa da para el capote Costa Rica y Nicaragua.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut de Ecuador"},{"name":"Reserva","color":"#6B4226","force":"Medium","story":"La casa escribe que sus tabacos maduran al menos tres años antes del liado y que sus puros reposan tres meses en un almacén climatizado, precisando Zechbauer una cámara de cedro; estos plazos valen para todas sus líneas, y sus páginas no dan los orígenes de Reserva.","vitolas":["Robusto","Toro"],"wrapper":"No divulgada"},{"name":"Don Luis","color":"#8B5A2B","force":"Medium-Full","story":"Gold Label en el sitio de la casa, que da una capa Connecticut de Ecuador, un capote de Ecuador y una tripa del Caribe. Casagranda nombra a Don Luis Santana Lamas, antiguo jefe de producción de la fábrica H. Upmann, en Cuba, y Zechbauer escribe que trabajó en el taller hasta su muerte.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Connecticut de Ecuador"},{"name":"El Puro (Red Label)","color":"#6B4423","force":null,"story":"Edición especial que la casa dice hecha enteramente con tabaco cultivado en sus propios campos, en las montañas volcánicas de Santiago de Puriscal: capa, capote y tripa de Costa Rica.","vitolas":[],"wrapper":"Costa Rica, dice la casa"}]',
  `gamme_de` = '[{"name":"Chaman","color":"#4A5D3A","force":"Medium-Full","story":"Der Name bedeutet Schamane; die Website des Hauses nennt sie auch El Mystico. Dort sind ein Connecticut-Deckblatt aus Ecuador, ein Umblatt aus Nicaragua und eine Einlage aus Costa Rica und Nicaragua angegeben; eine andere Seite des Hauses nennt für das Umblatt Costa Rica und Nicaragua.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut aus Ecuador"},{"name":"Reserva","color":"#6B4226","force":"Medium","story":"Das Haus schreibt, dass seine Tabake vor dem Rollen mindestens drei Jahre reifen und seine Zigarren drei Monate in einem klimatisierten Lager ruhen, wobei Zechbauer einen Zedernraum angibt; diese Fristen gelten für alle seine Linien, und seine Seiten nennen die Herkunft von Reserva nicht.","vitolas":["Robusto","Toro"],"wrapper":"Nicht offengelegt"},{"name":"Don Luis","color":"#8B5A2B","force":"Medium-Full","story":"Gold Label auf der Website des Hauses, die ein Connecticut-Deckblatt aus Ecuador, ein Umblatt aus Ecuador und eine Einlage aus der Karibik nennt. Casagranda nennt Don Luis Santana Lamas, früheren Produktionsleiter der Fabrik H. Upmann auf Kuba, und Zechbauer schreibt, er habe bis zu seinem Tod in der Werkstatt gearbeitet.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Connecticut aus Ecuador"},{"name":"El Puro (Red Label)","color":"#6B4423","force":null,"story":"Sonderedition, die nach Angaben des Hauses vollständig aus Tabak gefertigt ist, der auf den eigenen Feldern in den vulkanischen Bergen von Santiago de Puriscal angebaut wurde: Deckblatt, Umblatt und Einlage aus Costa Rica.","vitolas":[],"wrapper":"Costa Rica, sagt das Haus"}]',
  `gamme_zh` = '[{"name":"Chaman","color":"#4A5D3A","force":"Medium-Full","story":"这名字意为萨满；该号网站也称它为 El Mystico。网站给出的是产自厄瓜多尔的 Connecticut 茄衣、产自尼加拉瓜的茄套，以及产自哥斯达黎加和尼加拉瓜的填充烟叶；该号的另一个页面则给出茄套产自哥斯达黎加和尼加拉瓜。","vitolas":["Robusto","Toro","Corona"],"wrapper":"厄瓜多尔 Connecticut"},{"name":"Reserva","color":"#6B4226","force":"Medium","story":"该号写道，其烟叶在卷制前至少陈化三年，雪茄在空调库房中静置三个月，Zechbauer 注明为雪松房；这些期限适用于它所有的系列，其页面并未给出 Reserva 的产地。","vitolas":["Robusto","Toro"],"wrapper":"未公开"},{"name":"Don Luis","color":"#8B5A2B","force":"Medium-Full","story":"在该号网站上叫 Gold Label，该网站给出厄瓜多尔的 Connecticut 茄衣、厄瓜多尔的茄套和加勒比的填充烟叶。Casagranda 点名 Don Luis Santana Lamas，称其为古巴 H. Upmann 工厂的前生产主管；Zechbauer 则写道，他在作坊工作直到去世。","vitolas":["Robusto","Toro","Churchill"],"wrapper":"厄瓜多尔 Connecticut"},{"name":"El Puro (Red Label)","color":"#6B4423","force":null,"story":"特别版，据该号说完全以自家田地所种的烟叶制成，田地位于圣地亚哥-德普里斯卡尔的火山群山中：茄衣、茄套和填充烟叶均产自哥斯达黎加。","vitolas":[],"wrapper":"哥斯达黎加，据该号说"}]',
  `gamme_ar` = '[{"name":"Chaman","color":"#4A5D3A","force":"Medium-Full","story":"الاسم يعني الشامان؛ ويسمّيها موقع الدار أيضًا El Mystico. ويذكر الموقع غلافًا Connecticut من الإكوادور، ورباطًا من نيكاراغوا، وحشوة من كوستاريكا ونيكاراغوا؛ وتنسب صفحة أخرى من الدار الرباط إلى كوستاريكا ونيكاراغوا.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Connecticut من الإكوادور"},{"name":"Reserva","color":"#6B4226","force":"Medium","story":"تكتب الدار أنّ أتبغتها تنضج ثلاث سنوات على الأقلّ قبل اللفّ، وأنّ سيجاراتها تستريح ثلاثة شهور في مخزن مكيَّف الهواء، ويحدّد Zechbauer أنّه غرفة أرز؛ وهذه الآجال سارية على جميع خطوطها، ولا تذكر صفحاتها أصول Reserva.","vitolas":["Robusto","Toro"],"wrapper":"غير معلنة"},{"name":"Don Luis","color":"#8B5A2B","force":"Medium-Full","story":"Gold Label على موقع الدار، الذي يذكر غلافًا Connecticut من الإكوادور ورباطًا من الإكوادور وحشوة من الكاريبي. وتسمّي Casagranda دون لويس سانتانا لاماس، الرئيس السابق للإنتاج في مصنع H. Upmann بكوبا، ويكتب Zechbauer أنّه عمل في الورشة حتى وفاته.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Connecticut من الإكوادور"},{"name":"El Puro (Red Label)","color":"#6B4423","force":null,"story":"إصدار خاص تقول الدار إنّه مصنوع بالكامل من تبغ مزروع في حقولها الخاصة، في الجبال البركانية من سانتياغو دي بوريسكال: غلاف ورباط وحشوة من كوستاريكا.","vitolas":[],"wrapper":"كوستاريكا، تقول الدار"}]',
  `source` = IF(LOCATE(CAST('vegassantiago.com, cigars-vegasantiago.biz et casagranda-cigars.de (Marc Niehaus, Puriscal, 1 100 m, Luis Santana Lamas, Chaman, les bagues privées)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'vegassantiago.com, cigars-vegasantiago.biz et casagranda-cigars.de (Marc Niehaus, Puriscal, 1 100 m, Luis Santana Lamas, Chaman, les bagues privées)', 'cigars-vegasantiago.biz et casagranda-cigars.de (Marc Niehaus, Puriscal, Luis Santana Lamas, Chaman)'), `source`),
  `source` = IF(LOCATE(CAST('— aucune de ces sources ne donne l''année de fondation' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, '— aucune de ces sources ne donne l''année de fondation', '— aucune de ces sources ne donne l''année de la marque'), `source`),
  `source` = IF(LOCATE(CAST('cigars-vegasantiago.biz « Tobacco Farm and Premium Cigars Ma' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigars-vegasantiago.biz « Tobacco Farm and Premium Cigars Manufacture » (/en/about-us, page non datée, © 2026 : familles qui cultivent le tabac à Puriscal depuis plus de 80 ans, sans pesticide à cette altitude ; feuilles de ses cultures ou importées du Nicaragua, d''Équateur, des Caraïbes ; Marc Niehaus, Partner & International sales manager ; ni fondateur, ni Guzmán), /en/production (non datée : tabac importé du Nicaragua, d''Équateur, des États-Unis, d''Indonésie et des Caraïbes ; trois ans minimum de maturation) et /en/our-cigars (non datée : origines par ligne, Chaman et Don Luis cape Connecticut d''Équateur, El Puro 100 % costaricien, Reserva sans origine) ; nacion.com « Del tabaco quedan solo unos cuantos vestigios » (15 septembre 2011, en espagnol : Olman León propriétaire de la fábrica de Vegas de Santiago ; production arrêtée à Puriscal à la récolte 1997-1998 ; matière première du Pérou, d''Équateur et du Nicaragua, 15 % achetés à Pérez Zeledón) ; cigar-coop.com « Feature Story: Costa Rica In My Mind''s Eye » (17 mai 2019 : Andrés León, propriétaire et exploitant de Tabacos de Costa Rica ; marques Bombay Tobak, LH Premium Cigar, Selected Tobacco) et sa partie 2 (25 décembre 2020, même mention) ; casdaglicigars.com « Villa Casdagli Line » (page non datée : rencontre en 2012 à l''usine Vegas Santiago, nommée Tabacos de Costa Rica lors d''une visite en 2018) ; casagranda-cigars.de « VEGAS DE SANTIAGO » (non datée : fondée par Marc Niehaus ; Don Luis Santana Lamas, ancien chef de production de l''usine H. Upmann), « TABACOS DE COSTA RICA » (© 2026 : entreprise familiale née en 1997) et « La Flor de Montenegro » (Marc Niehaus travaille en étroite relation avec la famille Olman León Guzmán) ; zechbauer.de « At the Vegas de Santiago factory » (non datée : plus de 1 100 m, plus de 80 ans ; Don Luis Santana Lamas y a travaillé jusqu''à sa mort) ; vdg-cigars.com « Interview with Marc from Vegas de Santiago… » (site indépendant, page non datée : partenariat, droits de vente mondiaux de Don Rudy, prêt de 1998 à l''ouverture de la fabrique) ; cigarrspecialisten.se « Vegas de Santiago - Costa Rica » (détaillant suédois, non datée : Rudy et Lani Niehaus, famille Guzmán, Marc Niehaus dirige la société) ; rauchr.de « Vegas de Santiago Skull 77 Unicos » (27 juin 2018 : fabricant Tabacos de Costa Rica S.A.)')),
  `updated_at` = NOW()
 WHERE `name` = 'Vegas de Santiago';

-- ── Casdagli ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('celui-là même qui, à Puriscal, cultive son tabac à plus de mille cent mètres depuis plus de quatre-vingts ans, et qui a sa propre fiche dans cet atlas. Le Costa Rica n''est donc pas un pays sans terroir tabacole : il en a un, et Casdagli fait rouler ses Villa Casdagli à l''endroit précis où il se trouve.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'celui-là même qui, à Puriscal, cultive son tabac à plus de mille cent mètres depuis plus de quatre-vingts ans, et qui a sa propre fiche dans cet atlas. Le Costa Rica n''est donc pas un pays sans terroir tabacole : il en a un, et Casdagli fait rouler ses Villa Casdagli à l''endroit précis où il se trouve.', 'celui de Vegas de Santiago, qui a sa propre fiche dans cet atlas et dont la maison écrit cultiver du tabac à Puriscal depuis plus de quatre-vingts ans (à plus de mille cent mètres, dit Zechbauer). La Nación écrivait pourtant en 2011 que la production de tabac y avait cessé en 1997-1998 : Casdagli fait rouler ses Villa Casdagli à Puriscal, quel que soit l''état des champs alentour.'), `history`),
  `history_en` = IF(LOCATE(CAST('the very one that, at Puriscal, has grown its tobacco above eleven hundred metres for more than eighty years, and that has its own entry in this atlas. Costa Rica is therefore not a country without tobacco terroir: it has one, and Casdagli has its Villa Casdagli rolled at the exact spot where it lies.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'the very one that, at Puriscal, has grown its tobacco above eleven hundred metres for more than eighty years, and that has its own entry in this atlas. Costa Rica is therefore not a country without tobacco terroir: it has one, and Casdagli has its Villa Casdagli rolled at the exact spot where it lies.', 'that of Vegas de Santiago, which has its own entry in this atlas and whose house writes that it has grown tobacco at Puriscal for more than eighty years (above eleven hundred metres, says Zechbauer). La Nación wrote in 2011, however, that tobacco production there had ceased in 1997-1998: Casdagli has its Villa Casdagli rolled at Puriscal, whatever the state of the surrounding fields.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('el mismo que, en Puriscal, cultiva su tabaco a más de mil cien metros desde hace más de ochenta años, y que tiene su propia ficha en este atlas. Costa Rica no es, pues, un país sin terruño tabacalero: lo tiene, y Casdagli hace liar sus Villa Casdagli en el lugar exacto donde se encuentra.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'el mismo que, en Puriscal, cultiva su tabaco a más de mil cien metros desde hace más de ochenta años, y que tiene su propia ficha en este atlas. Costa Rica no es, pues, un país sin terruño tabacalero: lo tiene, y Casdagli hace liar sus Villa Casdagli en el lugar exacto donde se encuentra.', 'el de Vegas de Santiago, que tiene su propia ficha en este atlas y cuya casa escribe que cultiva tabaco en Puriscal desde hace más de ochenta años (a más de mil cien metros, dice Zechbauer). La Nación escribía sin embargo en 2011 que la producción de tabaco allí había cesado en 1997-1998: Casdagli hace liar sus Villa Casdagli en Puriscal, sea cual sea el estado de los campos de alrededor.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('eben jene, die in Puriscal seit mehr als achtzig Jahren auf über elfhundert Metern ihren Tabak anbaut und die in diesem Atlas einen eigenen Eintrag hat. Costa Rica ist also kein Land ohne Tabakterroir: Es hat eines, und Casdagli lässt seine Villa Casdagli genau dort rollen, wo es liegt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'eben jene, die in Puriscal seit mehr als achtzig Jahren auf über elfhundert Metern ihren Tabak anbaut und die in diesem Atlas einen eigenen Eintrag hat. Costa Rica ist also kein Land ohne Tabakterroir: Es hat eines, und Casdagli lässt seine Villa Casdagli genau dort rollen, wo es liegt.', 'diejenige von Vegas de Santiago, die in diesem Atlas einen eigenen Eintrag hat und deren Haus schreibt, es baue in Puriscal seit mehr als achtzig Jahren Tabak an (auf über elfhundert Metern, sagt Zechbauer). La Nación schrieb jedoch 2011, die Tabakproduktion habe dort 1997-1998 aufgehört: Casdagli lässt seine Villa Casdagli in Puriscal rollen, wie es auch um die Felder ringsum stehen mag.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('也就是在普里斯卡尔、于一千一百米以上种植烟叶已逾八十年、并在本图集中另有词条的那一家。可见哥斯达黎加并非没有烟草风土的国家：它有，而 Casdagli 正是在这片风土所在之处卷制它的 Villa Casdagli。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '也就是在普里斯卡尔、于一千一百米以上种植烟叶已逾八十年、并在本图集中另有词条的那一家。可见哥斯达黎加并非没有烟草风土的国家：它有，而 Casdagli 正是在这片风土所在之处卷制它的 Villa Casdagli。', '也就是 Vegas de Santiago 的那一家，它在本图集中另有词条，该号写道自己在普里斯卡尔种植烟草已逾八十年（据 Zechbauer 称，海拔一千一百米以上）。不过，La Nación 在2011年写道，当地的烟草生产已于1997-1998年停止：Casdagli 在普里斯卡尔卷制它的 Villa Casdagli，无论周边田地是何状况。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وهي بعينها التي تزرع تبغها في بوريسكال على ارتفاع يتجاوز ألفًا ومئة متر منذ أكثر من ثمانين سنة، ولها بطاقتها الخاصة في هذا الأطلس. فكوستاريكا إذن ليست بلدًا بلا تروا تبغي: لها تروا، وكاسداغلي تلفّ سيجارات Villa Casdagli في الموضع نفسه الذي يوجد فيه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وهي بعينها التي تزرع تبغها في بوريسكال على ارتفاع يتجاوز ألفًا ومئة متر منذ أكثر من ثمانين سنة، ولها بطاقتها الخاصة في هذا الأطلس. فكوستاريكا إذن ليست بلدًا بلا تروا تبغي: لها تروا، وكاسداغلي تلفّ سيجارات Villa Casdagli في الموضع نفسه الذي يوجد فيه.', 'وهي ورشة Vegas de Santiago، التي لها بطاقتها الخاصة في هذا الأطلس، وتكتب دارها أنّها تزرع التبغ في بوريسكال منذ أكثر من ثمانين سنة (على ارتفاع يتجاوز ألفًا ومئة متر، بحسب Zechbauer). غير أنّ La Nación كتبت سنة 2011 أنّ إنتاج التبغ فيها توقّف في 1997-1998: تلفّ Casdagli سيجارات Villa Casdagli في بوريسكال، أيًّا كانت حال الحقول المحيطة بها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Casdagli';

