-- ── Bombay Tobak ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('la fabrique que l''atlas décrit à la fiche Vegas de Santiago, son ancien nom, et qui roule aussi Villa Casdagli et les bagues de Zechbauer. MBombay est donc la troisième marque de cet atlas à sortir de cet atelier, et la fiche Vegas de Santiago le dit désormais.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'la fabrique que l''atlas décrit à la fiche Vegas de Santiago, son ancien nom, et qui roule aussi Villa Casdagli et les bagues de Zechbauer. MBombay est donc la troisième marque de cet atlas à sortir de cet atelier, et la fiche Vegas de Santiago le dit désormais.', 'la fabrique que l''atlas décrit à la fiche Vegas de Santiago (Casdagli écrit qu''elle était alors connue sous ce nom) et qui roule aussi Selected Tobacco, Villa Casdagli, Malekö, Skull 77 et les Zechbauer Royales. Cigar Coop en nomme Andrés León propriétaire et exploitant, et compte Bombay Tobak, avec Selected Tobacco, parmi les marques qui en sortent.'), `history`),
  `history_en` = IF(LOCATE(CAST('the factory this atlas describes at the Vegas de Santiago entry, its former name, and which also rolls Villa Casdagli and Zechbauer''s bands. MBombay is thus the third brand of this atlas to come out of that workshop, and the Vegas de Santiago entry now says so.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'the factory this atlas describes at the Vegas de Santiago entry, its former name, and which also rolls Villa Casdagli and Zechbauer''s bands. MBombay is thus the third brand of this atlas to come out of that workshop, and the Vegas de Santiago entry now says so.', 'the factory this atlas describes at the Vegas de Santiago entry (Casdagli writes that it was then known by that name) and which also rolls Selected Tobacco, Villa Casdagli, Malekö, Skull 77 and the Zechbauer Royales. Cigar Coop names Andrés León as its owner and operator, and counts Bombay Tobak, with Selected Tobacco, among the brands that come out of it.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('la fábrica que este atlas describe en la ficha Vegas de Santiago, su antiguo nombre, y que lía también Villa Casdagli y las anillas de Zechbauer. MBombay es pues la tercera marca de este atlas que sale de ese taller, y la ficha Vegas de Santiago lo dice desde ahora.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'la fábrica que este atlas describe en la ficha Vegas de Santiago, su antiguo nombre, y que lía también Villa Casdagli y las anillas de Zechbauer. MBombay es pues la tercera marca de este atlas que sale de ese taller, y la ficha Vegas de Santiago lo dice desde ahora.', 'la fábrica que este atlas describe en la ficha Vegas de Santiago (Casdagli escribe que se conocía entonces con ese nombre) y que lía también Selected Tobacco, Villa Casdagli, Malekö, Skull 77 y los Zechbauer Royales. Cigar Coop nombra a Andrés León su propietario y operador, y cuenta a Bombay Tobak, con Selected Tobacco, entre las marcas que salen de ella.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('der Fabrik, die dieser Atlas im Eintrag Vegas de Santiago beschreibt, ihrem früheren Namen, und die auch Villa Casdagli und die Bauchbinden von Zechbauer rollt. MBombay ist damit die dritte Marke dieses Atlas aus dieser Werkstatt, und der Eintrag Vegas de Santiago sagt es nun.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'der Fabrik, die dieser Atlas im Eintrag Vegas de Santiago beschreibt, ihrem früheren Namen, und die auch Villa Casdagli und die Bauchbinden von Zechbauer rollt. MBombay ist damit die dritte Marke dieses Atlas aus dieser Werkstatt, und der Eintrag Vegas de Santiago sagt es nun.', 'der Fabrik, die dieser Atlas im Eintrag Vegas de Santiago beschreibt (Casdagli schreibt, sie sei damals unter diesem Namen bekannt gewesen) und die auch Selected Tobacco, Villa Casdagli, Malekö, Skull 77 und die Zechbauer Royales rollt. Cigar Coop nennt Andrés León als ihren Eigentümer und Betreiber und zählt Bombay Tobak zusammen mit Selected Tobacco zu den Marken, die aus ihr hervorgehen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集在 Vegas de Santiago 词条描述的那家工厂，那是它的旧名，它也卷制 Villa Casdagli 与 Zechbauer 的茄标。MBombay 因此是本图集第三个出自该作坊的品牌，Vegas de Santiago 词条如今已写明。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集在 Vegas de Santiago 词条描述的那家工厂，那是它的旧名，它也卷制 Villa Casdagli 与 Zechbauer 的茄标。MBombay 因此是本图集第三个出自该作坊的品牌，Vegas de Santiago 词条如今已写明。', '本图集在 Vegas de Santiago 词条描述的那家工厂（Casdagli 写道，它当时以此名为人所知），它也卷制 Selected Tobacco、Villa Casdagli、Malekö、Skull 77 和 Zechbauer Royales。Cigar Coop 称安德烈斯·莱昂为该厂业主兼经营者，并把 Bombay Tobak 与 Selected Tobacco 一同算作出自该厂的品牌。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('المصنع الذي يصفه هذا الأطلس في بطاقة Vegas de Santiago، اسمه السابق، والذي يلفّ أيضًا Villa Casdagli وأحزمة Zechbauer. فـMBombay إذن العلامة الثالثة في هذا الأطلس الخارجة من تلك الورشة، وبطاقة Vegas de Santiago تقول ذلك الآن.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'المصنع الذي يصفه هذا الأطلس في بطاقة Vegas de Santiago، اسمه السابق، والذي يلفّ أيضًا Villa Casdagli وأحزمة Zechbauer. فـMBombay إذن العلامة الثالثة في هذا الأطلس الخارجة من تلك الورشة، وبطاقة Vegas de Santiago تقول ذلك الآن.', 'المصنع الذي يصفه هذا الأطلس في بطاقة Vegas de Santiago (تكتب Casdagli أنّه كان معروفًا آنذاك بهذا الاسم) والذي يلفّ أيضًا Selected Tobacco وVilla Casdagli وMalekö وSkull 77 وZechbauer Royales. ويسمّي Cigar Coop أندريس ليون مالكًا له ومشغّلًا، ويعدّ Bombay Tobak، مع Selected Tobacco، من العلامات الخارجة منه.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Bombay Tobak';

UPDATE `brands` SET
