-- ── Brun del Ré ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''atlas classe ici une maison qui roule et, pour une ligne, cultive — une exception dans un pays d''ateliers, comme Vegas de Santiago à Puriscal.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''atlas classe ici une maison qui roule et, pour une ligne, cultive — une exception dans un pays d''ateliers, comme Vegas de Santiago à Puriscal.', 'L''atlas classe ici une maison qui roule et, pour une ligne, emploie un tabac entièrement costaricien, venu d''un planteur du sud du pays — une exception dans un pays d''ateliers, que Vegas de Santiago, à Puriscal, dit partager pour une part de ses feuilles.'), `history`),
  `history_en` = IF(LOCATE(CAST('This atlas classifies here a house that rolls and, for one line, grows — an exception in a country of workshops, like Vegas de Santiago in Puriscal.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'This atlas classifies here a house that rolls and, for one line, grows — an exception in a country of workshops, like Vegas de Santiago in Puriscal.', 'This atlas classifies here a house that rolls and, for one line, uses an entirely Costa Rican tobacco, from a planter in the south of the country — an exception in a country of workshops, one that Vegas de Santiago, in Puriscal, says it shares for part of its leaves.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Este atlas clasifica aquí una casa que lía y, para una línea, cultiva — una excepción en un país de talleres, como Vegas de Santiago en Puriscal.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Este atlas clasifica aquí una casa que lía y, para una línea, cultiva — una excepción en un país de talleres, como Vegas de Santiago en Puriscal.', 'Este atlas clasifica aquí una casa que lía y, para una línea, emplea un tabaco enteramente costarricense, procedente de un cultivador del sur del país — una excepción en un país de talleres, que Vegas de Santiago, en Puriscal, dice compartir para una parte de sus hojas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Dieser Atlas ordnet hier ein Haus ein, das rollt und, für eine Linie, anbaut — eine Ausnahme in einem Land der Werkstätten, wie Vegas de Santiago in Puriscal.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Dieser Atlas ordnet hier ein Haus ein, das rollt und, für eine Linie, anbaut — eine Ausnahme in einem Land der Werkstätten, wie Vegas de Santiago in Puriscal.', 'Dieser Atlas ordnet hier ein Haus ein, das rollt und, für eine Linie, einen vollständig costa-ricanischen Tabak verwendet, von einem Pflanzer aus dem Süden des Landes — eine Ausnahme in einem Land der Werkstätten; Vegas de Santiago in Puriscal teilt sie nach eigener Aussage für einen Teil seiner Blätter.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集在此收录一家既卷制、又为一条线种植的公司——在一个作坊之国里的例外，一如普里斯卡尔的 Vegas de Santiago。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集在此收录一家既卷制、又为一条线种植的公司——在一个作坊之国里的例外，一如普里斯卡尔的 Vegas de Santiago。', '本图集在此收录一家既卷制、又为一条线使用完全产自哥斯达黎加、来自该国南部一位种植者的烟叶的公司——在一个作坊之国里的例外，普里斯卡尔的 Vegas de Santiago 称，就其一部分烟叶而言也是如此。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يصنّف هذا الأطلس هنا دارًا تلفّ، وتزرع لخطّ واحد — استثناءٌ في بلد الورش، مثل Vegas de Santiago في بوريسكال.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يصنّف هذا الأطلس هنا دارًا تلفّ، وتزرع لخطّ واحد — استثناءٌ في بلد الورش، مثل Vegas de Santiago في بوريسكال.', 'يصنّف هذا الأطلس هنا دارًا تلفّ، وتستخدم لخطٍّ واحد تبغًا كوستاريكيًّا بالكامل، جاءها من مزارعٍ في جنوب البلاد — استثناءٌ في بلد الورش، تقول Vegas de Santiago في بوريسكال إنّها تشترك فيه بالنسبة إلى جزء من أوراقها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Brun del Ré';

