  `notes_de` = IF(LOCATE(CAST('Der Zensus von 2026 zählt zehn Einträge' AS BINARY), CAST(`notes_de` AS BINARY)) > 0, REPLACE(`notes_de`, 'Der Zensus von 2026 zählt zehn Einträge', 'Der Atlas zählt zwölf Einträge'), `notes_de`),
