  `notes_ar` = IF(LOCATE(CAST('إحصاء 2026 عشر بطاقات' AS BINARY), CAST(`notes_ar` AS BINARY)) > 0, REPLACE(`notes_ar`, 'إحصاء 2026 عشر بطاقات', 'الأطلس اثنتي عشرة بطاقةً'), `notes_ar`),
