 WHERE `id` = 'costarica';

UPDATE `producer_countries` SET
  `notes` = IF(LOCATE(CAST('Puriscal, à plus de mille mètres, est le seul lieu du pays où l''on cultive ce qu''on roule.' AS BINARY), CAST(`notes` AS BINARY)) > 0, REPLACE(`notes`, 'Puriscal, à plus de mille mètres, est le seul lieu du pays où l''on cultive ce qu''on roule.', 'À Puriscal, Vegas de Santiago (à plus de mille mètres, dit Zechbauer) et IGM disent cultiver une part de ce qu''elles roulent et importer le reste ; La Nación écrivait en 2011 que la production de tabac y avait cessé à la récolte 1997-1998.'), `notes`),
  `notes_en` = IF(LOCATE(CAST('Puriscal, above a thousand metres, is the only place in the country where what is rolled is also grown.' AS BINARY), CAST(`notes_en` AS BINARY)) > 0, REPLACE(`notes_en`, 'Puriscal, above a thousand metres, is the only place in the country where what is rolled is also grown.', 'In Puriscal, Vegas de Santiago (above a thousand metres, says Zechbauer) and IGM say they grow part of what they roll and import the rest; La Nación wrote in 2011 that tobacco production there had ceased with the 1997-1998 harvest.'), `notes_en`),
  `notes_es` = IF(LOCATE(CAST('Puriscal, a más de mil metros, es el único lugar del país donde se cultiva lo que se lía.' AS BINARY), CAST(`notes_es` AS BINARY)) > 0, REPLACE(`notes_es`, 'Puriscal, a más de mil metros, es el único lugar del país donde se cultiva lo que se lía.', 'En Puriscal, Vegas de Santiago (a más de mil metros, dice Zechbauer) e IGM dicen cultivar una parte de lo que lían e importar el resto; La Nación escribía en 2011 que la producción de tabaco había cesado allí en la cosecha 1997-1998.'), `notes_es`),
  `notes_de` = IF(LOCATE(CAST('Puriscal, über tausend Meter hoch, ist der einzige Ort des Landes, an dem angebaut wird, was gerollt wird.' AS BINARY), CAST(`notes_de` AS BINARY)) > 0, REPLACE(`notes_de`, 'Puriscal, über tausend Meter hoch, ist der einzige Ort des Landes, an dem angebaut wird, was gerollt wird.', 'In Puriscal geben Vegas de Santiago (auf über tausend Metern, sagt Zechbauer) und IGM an, einen Teil dessen, was sie rollen, anzubauen und den Rest zu importieren; La Nación schrieb 2011, die Tabakproduktion dort habe mit der Ernte 1997-1998 aufgehört.'), `notes_de`),
  `notes_zh` = IF(LOCATE(CAST('海拔一千多米的普里斯卡尔是全国唯一种自己所卷之叶的地方。' AS BINARY), CAST(`notes_zh` AS BINARY)) > 0, REPLACE(`notes_zh`, '海拔一千多米的普里斯卡尔是全国唯一种自己所卷之叶的地方。', '在普里斯卡尔，Vegas de Santiago（据 Zechbauer 称，海拔一千多米）与 IGM 称自己种植所卷之叶的一部分，其余进口；La Nación 在2011年写道，当地的烟草生产止于1997-1998年度的收获。'), `notes_zh`),
  `notes_ar` = IF(LOCATE(CAST('وبوريسكال، فوق ألف متر، هي المكان الوحيد في البلاد الذي يُزرع فيه ما يُلفّ.' AS BINARY), CAST(`notes_ar` AS BINARY)) > 0, REPLACE(`notes_ar`, 'وبوريسكال، فوق ألف متر، هي المكان الوحيد في البلاد الذي يُزرع فيه ما يُلفّ.', 'وفي بوريسكال، تقول Vegas de Santiago (فوق ألف متر، بحسب Zechbauer) وIGM إنّهما تزرعان جزءًا ممّا تلفّانه وتستوردان الباقي؛ وكتبت La Nación سنة 2011 أنّ إنتاج التبغ فيها توقّف عند حصاد 1997-1998.'), `notes_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'costarica';

UPDATE `producer_countries` SET `notes_en` = 'A single player, but one aiming at the top of the market rather than at volume.

No longer a single player: the atlas has twelve entries and three named factories — Tabacos de Costa Rica in Puriscal, Brun del Ré in Escazú, IGM in San José — plus the plant El Septimo claims. In Puriscal, Vegas de Santiago (above a thousand metres, says Zechbauer) and IGM say they grow part of what they roll and import the rest; La Nación wrote in 2011 that tobacco production there had ceased with the 1997-1998 harvest. Tabacos de la Cordillera, of Puriscal, no longer has an estate and has no press at all: not written.', `updated_at` = NOW() WHERE `id` = 'costarica';

UPDATE `producer_countries` SET
  `brands` = '[{"desc":"Du dessinateur du Behike à sa propre maison","name":"Atabey","iconic":true},{"desc":"Le versant classique de Selected Tobacco","name":"Byron","iconic":false},{"desc":"Des tabacs mûris cinq ans avant roulage","name":"Bandolero","iconic":false},{"desc":"Maison britannique sans champs, roulée au Costa Rica","name":"Casdagli","iconic":false},{"desc":"Nelson Alfonso — la maison derrière Atabey, Byron et Bandolero","name":"Selected Tobacco","iconic":false},{"desc":"Atelier de Puriscal, qui roule aussi Selected Tobacco, Casdagli, Bombay Tobak, Malekö et Skull 77","name":"Vegas de Santiago","iconic":true},{"desc":"2014 — MBombay, de Mel Shah ; roulée chez Tabacos de Costa Rica, à Santiago de Puriscal","name":"Bombay Tobak","iconic":false},{"desc":"Carlo Corazza, 2006 — usine propre à Escazú ; 1787 Libertad en tabac costaricien","name":"Brun del Ré","iconic":true},{"desc":"Genève 2005, Younan depuis 2019 — le luxe roulé au Costa Rica","name":"El Septimo","iconic":false},{"desc":"San José, 1997 selon la maison — la fabrique boutique qui roule Casdagli","name":"IGM Cigars","iconic":false},{"desc":"Custom Blend lancée en 2015 ; roulée chez Tabacos de Costa Rica, à Santiago de Puriscal","name":"Malekö","iconic":false},{"desc":"2014 — Laurent Taha ; roulée chez Tabacos de Costa Rica, à Santiago de Puriscal","name":"Skull 77","iconic":false}]',
  `tabacaleras` = '["Tabacos de Costa Rica (Santiago de Puriscal)","IGM Cigars (San José)","Brun del Ré (Escazú)","El Septimo Cigar Factory (revendiquée)"]',
  `updated_at` = NOW()
 WHERE `id` = 'costarica';

-- ── Salon 182 : Arturo Fuente — Boutique Santiago ──
UPDATE `lounges` SET
  `description_zh` = '多米尼加共和国圣地亚哥的 Fuente 家族精品店——除 Château de la Fuente 之外，唯一保证 Opus X 供货的销售点。',
  `description_ar` = 'بوتيك عائلة Fuente في سانتياغو بالجمهورية الدومينيكية — نقطة البيع الوحيدة خارج Château de la Fuente التي يُضمن فيها توفّر إمدادات Opus X.',
  `updated_at` = NOW()
 WHERE `id` = 182 AND `name` = 'Arturo Fuente — Boutique Santiago';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'lounges', l.`id`, 'description', g.lang, SHA1(l.`description`), 'machine', NULL, NOW()
  FROM `lounges` l
  JOIN (SELECT 'zh' lang UNION ALL SELECT 'ar') g
 WHERE l.`id` = 182
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Vegas de Santiago' hote, 'gamme' champ
        UNION ALL SELECT 'Vegas de Santiago' hote, 'history' champ
        UNION ALL SELECT 'Casdagli' hote, 'history' champ
        UNION ALL SELECT 'Bombay Tobak' hote, 'history' champ
        UNION ALL SELECT 'Brun del Ré' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

-- ── Les sceaux des notes de pays réécrites ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'producer_countries', p.`id`, 'notes', l.lang, SHA1(p.`notes`), 'machine', NULL, NOW()
  FROM `producer_countries` p
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE p.`id` IN ('costarica')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

UPDATE `translation_status` SET `statut` = 'relu', `relecteur` = 'expert-traduction (agent)', `maj` = NOW() WHERE `entite` = 'producer_countries' AND `entite_id` = 'costarica' AND `champ` = 'notes' AND `lang` = 'en';

