-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Vegas de Santiago' AS hote, 'fr' AS lang, 'founded' AS quoi, (CAST(`founded` AS BINARY) = CAST('Non précisée — Guzmán et Niehaus, Puriscal' AS BINARY)) AS ok FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Santiago de Puriscal, San José — Tabacos de Costa Rica S.A., alors connue sous le nom de Vegas Santiago (Casdagli) ; propriétaires nommés : Olman León (2011), Andrés León (2019)' AS BINARY)) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La maison Vegas de Santiago écrit cultiver une part de ses feuilles et importer le reste.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas de Santiago est ce qui dément la formule — elle cultive ce qu''elle roule.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The Vegas de Santiago house writes that it grows part of its leaf and imports the rest.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas de Santiago is what contradicts the formula — it grows what it rolls.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La casa Vegas de Santiago escribe que cultiva una parte de sus hojas e importa el resto.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas de Santiago es lo que desmiente la fórmula — cultiva lo que lía.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Das Haus Vegas de Santiago schreibt, es baue einen Teil seiner Blätter an und importiere den Rest.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas de Santiago ist das, was die Formel widerlegt — es baut an, was es rollt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Vegas de Santiago 公司写道，自己种植一部分烟叶，其余进口。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Vegas de Santiago 正是推翻这一说法的存在——它种自己所卷的烟叶。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تكتب دار Vegas de Santiago أنّها تزرع جزءًا من أوراقها وتستورد الباقي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أمّا فيغاس دي سانتياغو فهي ما يكذّب هذه الصيغة — إذ تزرع ما تلفّه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La maison écrit que ses familles cultivent du tabac dans les montagnes volcaniques de Santiago de Puriscal, au sud-ouest de San José, depuis plus de quatre-vingts ans (à plus de mille cent mètres, dit Zechbauer), et qu''elle se passe de pesticides à cette altitude. La Nación écrivait en 2011 que la production de tabac avait cessé à Puriscal à la récolte 1997-1998 et que l''atelier faisait venir sa matière première du Pérou, d''Équateur et du Nicaragua, 15 % seulement s''achetant à Pérez Zeledón.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Ses champs sont à Santiago de Puriscal, dans les montagnes volcaniques au sud-ouest de San José, à plus de mille cent mètres. On y plante du tabac depuis plus de quatre-vingts ans. L''altitude tient lieu de traitement : la maison explique qu''elle se passe de pesticides parce que les ravageurs ne montent pas si haut.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The house writes that its families have grown tobacco in the volcanic mountains of Santiago de Puriscal, south-west of San José, for more than eighty years (above eleven hundred metres, says Zechbauer), and that it does without pesticides at that altitude. La Nación wrote in 2011 that tobacco production had ceased in Puriscal with the 1997-1998 harvest and that the workshop brought in its raw material from Peru, Ecuador and Nicaragua, only 15% being bought in Pérez Zeledón.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Its fields are at Santiago de Puriscal, in the volcanic mountains south-west of San José, above eleven hundred metres. Tobacco has been planted there for more than eighty years. Altitude serves as treatment: the house explains that it does without pesticides because the pests do not climb that high.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La casa escribe que sus familias cultivan tabaco en las montañas volcánicas de Santiago de Puriscal, al suroeste de San José, desde hace más de ochenta años (a más de mil cien metros, dice Zechbauer), y que prescinde de pesticidas a esa altitud. La Nación escribía en 2011 que la producción de tabaco había cesado en Puriscal en la cosecha 1997-1998 y que el taller hacía venir su materia prima de Perú, Ecuador y Nicaragua, comprándose en Pérez Zeledón solo el 15 %.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Sus campos están en Santiago de Puriscal, en las montañas volcánicas al suroeste de San José, a más de mil cien metros. Allí se planta tabaco desde hace más de ochenta años. La altitud hace las veces de tratamiento: la casa explica que prescinde de pesticidas porque las plagas no suben tan alto.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Das Haus schreibt, dass seine Familien in den vulkanischen Bergen von Santiago de Puriscal, südwestlich von San José, seit mehr als achtzig Jahren Tabak anbauen (auf über elfhundert Metern, sagt Zechbauer) und dass es in dieser Höhe ohne Pestizide auskommt. La Nación schrieb 2011, die Tabakproduktion habe in Puriscal mit der Ernte 1997-1998 aufgehört und die Werkstatt lasse ihren Rohstoff aus Peru, Ecuador und Nicaragua kommen, wobei nur 15 % in Pérez Zeledón gekauft würden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Seine Felder liegen in Santiago de Puriscal, in den vulkanischen Bergen südwestlich von San José, auf über elfhundert Metern. Seit mehr als achtzig Jahren wird dort Tabak gepflanzt. Die Höhe ersetzt die Behandlung: Das Haus erklärt, es komme ohne Pestizide aus, weil die Schädlinge nicht so hoch steigen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('该号写道，旗下各家族在圣何塞西南火山群山中的圣地亚哥-德普里斯卡尔种植烟草已逾八十年（据 Zechbauer 称，海拔一千一百米以上），且在这一海拔高度上无须农药。La Nación 在2011年写道，普里斯卡尔的烟草生产止于1997-1998年度的收获，作坊的原料从秘鲁、厄瓜多尔和尼加拉瓜运来，仅15%购自 Pérez Zeledón。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('它的田地在圣何塞西南火山群山中的圣地亚哥-德普里斯卡尔，海拔一千一百米以上。此地种植烟草已逾八十年。海拔本身即是处理之法：该号称，虫害爬不了这么高，因此无须农药。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تكتب الدار أنّ عائلاتها تزرع التبغ في الجبال البركانية من سانتياغو دي بوريسكال، جنوب غربي سان خوسيه، منذ أكثر من ثمانين سنة (على ارتفاع يتجاوز ألفًا ومئة متر، بحسب Zechbauer)، وأنّها تستغني عن المبيدات عند هذا الارتفاع. وكتبت La Nación سنة 2011 أنّ إنتاج التبغ توقّف في بوريسكال عند حصاد 1997-1998، وأنّ الورشة كانت تستقدم مادتها الأولية من بيرو والإكوادور ونيكاراغوا، ولا يُشترى من Pérez Zeledón سوى 15%.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('حقولها في سانتياغو دي بوريسكال، في الجبال البركانية جنوب غربي سان خوسيه، على ارتفاع يتجاوز ألفًا ومئة متر. ويُزرع التبغ هناك منذ أكثر من ثمانين سنة. والارتفاع يقوم مقام المعالجة: تقول الدار إنّها تستغني عن المبيدات لأنّ الآفات لا تصعد إلى هذا العلوّ.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Qui l''a fondée se lit de deux façons : Marc Niehaus seul, écrit Casagranda, son distributeur allemand ; les familles Niehaus et Guzmán ensemble, écrit Cigarrspecialisten, détaillant suédois. La maison, sans nommer de fondateur, présente Marc Niehaus comme partenaire et responsable des ventes internationales. Casagranda date de 1997 la manufacture familiale Tabacos de Costa Rica ; un entretien avec Marc Niehaus, publié sur vdg-cigars.com, situe en 1998 l''ouverture de la fabrique ; aucune source citée ne donne l''année de la marque.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Marc Niehaus l''a fondée. Aucune source consultable n''en donne l''année, et cette fiche préfère le dire que l''inventer — la même règle que pour Kolumbus aux Canaries. Un maître cubain, Luis Santana Lamas, y a apporté la manière de traiter la feuille et de rouler ; la maison le nomme, et son prénom est resté sur une gamme.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
UNION ALL SELECT 'Vegas de Santiago', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Who founded it can be read in two ways: Marc Niehaus alone, writes Casagranda, its German distributor; the Niehaus and Guzmán families together, writes Cigarrspecialisten, a Swedish retailer. The house, without naming a founder, presents Marc Niehaus as a partner and head of international sales. Casagranda dates the family factory Tabacos de Costa Rica to 1997; an interview with Marc Niehaus, published on vdg-cigars.com, places the opening of the factory in 1998; no cited source gives the year of the brand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Vegas de Santiago'
