UNION ALL SELECT 'pays costarica', 'fr', 'notes 2 (nouveau texte)', (LOCATE(CAST('À Puriscal, Vegas de Santiago (à plus de mille mètres, dit Zechbauer) et IGM disent cultiver une part de ce qu''elles roulent et importer le reste ; La Nación écrivait en 2011 que la production de tabac y avait cessé à la récolte 1997-1998.' AS BINARY), CAST(`notes` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'fr', 'notes 2 (ancien texte parti)', (LOCATE(CAST('Puriscal, à plus de mille mètres, est le seul lieu du pays où l''on cultive ce qu''on roule.' AS BINARY), CAST(`notes` AS BINARY)) = 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'en', 'notes 2 (nouveau texte)', (LOCATE(CAST('In Puriscal, Vegas de Santiago (above a thousand metres, says Zechbauer) and IGM say they grow part of what they roll and import the rest; La Nación wrote in 2011 that tobacco production there had ceased with the 1997-1998 harvest.' AS BINARY), CAST(`notes_en` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'en', 'notes 2 (ancien texte parti)', (LOCATE(CAST('Puriscal, above a thousand metres, is the only place in the country where what is rolled is also grown.' AS BINARY), CAST(`notes_en` AS BINARY)) = 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'es', 'notes 2 (nouveau texte)', (LOCATE(CAST('En Puriscal, Vegas de Santiago (a más de mil metros, dice Zechbauer) e IGM dicen cultivar una parte de lo que lían e importar el resto; La Nación escribía en 2011 que la producción de tabaco había cesado allí en la cosecha 1997-1998.' AS BINARY), CAST(`notes_es` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'es', 'notes 2 (ancien texte parti)', (LOCATE(CAST('Puriscal, a más de mil metros, es el único lugar del país donde se cultiva lo que se lía.' AS BINARY), CAST(`notes_es` AS BINARY)) = 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'de', 'notes 2 (nouveau texte)', (LOCATE(CAST('In Puriscal geben Vegas de Santiago (auf über tausend Metern, sagt Zechbauer) und IGM an, einen Teil dessen, was sie rollen, anzubauen und den Rest zu importieren; La Nación schrieb 2011, die Tabakproduktion dort habe mit der Ernte 1997-1998 aufgehört.' AS BINARY), CAST(`notes_de` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'de', 'notes 2 (ancien texte parti)', (LOCATE(CAST('Puriscal, über tausend Meter hoch, ist der einzige Ort des Landes, an dem angebaut wird, was gerollt wird.' AS BINARY), CAST(`notes_de` AS BINARY)) = 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'zh', 'notes 2 (nouveau texte)', (LOCATE(CAST('在普里斯卡尔，Vegas de Santiago（据 Zechbauer 称，海拔一千多米）与 IGM 称自己种植所卷之叶的一部分，其余进口；La Nación 在2011年写道，当地的烟草生产止于1997-1998年度的收获。' AS BINARY), CAST(`notes_zh` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'zh', 'notes 2 (ancien texte parti)', (LOCATE(CAST('海拔一千多米的普里斯卡尔是全国唯一种自己所卷之叶的地方。' AS BINARY), CAST(`notes_zh` AS BINARY)) = 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'ar', 'notes 2 (nouveau texte)', (LOCATE(CAST('وفي بوريسكال، تقول Vegas de Santiago (فوق ألف متر، بحسب Zechbauer) وIGM إنّهما تزرعان جزءًا ممّا تلفّانه وتستوردان الباقي؛ وكتبت La Nación سنة 2011 أنّ إنتاج التبغ فيها توقّف عند حصاد 1997-1998.' AS BINARY), CAST(`notes_ar` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'ar', 'notes 2 (ancien texte parti)', (LOCATE(CAST('وبوريسكال، فوق ألف متر، هي المكان الوحيد في البلاد الذي يُزرع فيه ما يُلفّ.' AS BINARY), CAST(`notes_ar` AS BINARY)) = 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'en', 'notes relues (texte)', (CAST(`notes_en` AS BINARY) = CAST('A single player, but one aiming at the top of the market rather than at volume.

No longer a single player: the atlas has twelve entries and three named factories — Tabacos de Costa Rica in Puriscal, Brun del Ré in Escazú, IGM in San José — plus the plant El Septimo claims. In Puriscal, Vegas de Santiago (above a thousand metres, says Zechbauer) and IGM say they grow part of what they roll and import the rest; La Nación wrote in 2011 that tobacco production there had ceased with the 1997-1998 harvest. Tabacos de la Cordillera, of Puriscal, no longer has an estate and has no press at all: not written.' AS BINARY)) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'en', 'notes relues (sceau)', ((SELECT `statut` FROM `translation_status` WHERE `entite` = 'producer_countries' AND `entite_id` = 'costarica' AND `champ` = 'notes' AND `lang` = 'en') = 'relu') FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'fr', 'desc Vegas de Santiago', (LOCATE(CAST('Atelier de Puriscal, qui roule aussi Selected Tobacco, Casdagli, Bombay Tobak, Malekö et Skull 77' AS BINARY), CAST(`brands` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'fr', 'desc Bombay Tobak', (LOCATE(CAST('2014 — MBombay, de Mel Shah ; roulée chez Tabacos de Costa Rica, à Santiago de Puriscal' AS BINARY), CAST(`brands` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'pays costarica', 'fr', 'tabacalera retirée : Selected Tobacco (Puriscal)', (NOT JSON_CONTAINS(`tabacaleras`, '"Selected Tobacco (Puriscal)"')) FROM `producer_countries` WHERE `id` = 'costarica'
UNION ALL SELECT 'salon 182', 'zh', 'description refaite', (CAST(`description_zh` AS BINARY) = CAST('多米尼加共和国圣地亚哥的 Fuente 家族精品店——除 Château de la Fuente 之外，唯一保证 Opus X 供货的销售点。' AS BINARY)) FROM `lounges` WHERE `id` = 182
UNION ALL SELECT 'salon 182', 'ar', 'description refaite', (CAST(`description_ar` AS BINARY) = CAST('بوتيك عائلة Fuente في سانتياغو بالجمهورية الدومينيكية — نقطة البيع الوحيدة خارج Château de la Fuente التي يُضمن فيها توفّر إمدادات Opus X.' AS BINARY)) FROM `lounges` WHERE `id` = 182;
SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme') AND b.`name` IN ('Vegas de Santiago','Casdagli','Selected Tobacco','Atabey','Bandolero','Byron','Bombay Tobak','Brun del Ré')) = 0 AS sceaux_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` p ON p.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(p.`notes`) AND p.`id` IN ('costarica')) = 0 AS sceaux_pays_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `lounges` s ON s.`id` = t.`entite_id` AND t.`entite` = 'lounges'
         WHERE t.`champ` = 'description' AND t.`source_hash` <> SHA1(s.`description`) AND s.`id` IN (182)) = 0 AS sceaux_salons_a_jour,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 255') AS journal_non_tronque;
